#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>

std::mutex m;
std::condition_variable cv;
std::queue<int> orders;
bool done = false;

void producer() {
    for (int id = 1; id <= 5; ++id) {
        {
            std::lock_guard<std::mutex> lk(m);
            orders.push(id);
        }
        cv.notify_one();
    }
    {
        std::lock_guard<std::mutex> lk(m);
        done = true;
    }
    cv.notify_all();
}

void consumer() {
    while (true) {
        std::unique_lock<std::mutex> lk(m);
        cv.wait(lk, [] { return !orders.empty() || done; });
        if (!orders.empty()) {
            int id = orders.front();
            orders.pop();
            lk.unlock();
            // process order `id` outside the lock
        } else {
            break;   // done and empty: exit
        }
    }
}

void ThreadPool::submit(std::function<void()> task) {
    {
        std::lock_guard<std::mutex> lk(m_);
        tasks_.push(std::move(task));
    }
    cv_.notify_one();
}

void ThreadPool::worker_loop() {
    while (true) {
        std::function<void()> task;
        {
            std::unique_lock<std::mutex> lk(m_);
            cv_.wait(lk, [this] { return stop_ || !tasks_.empty(); });
            if (stop_ && tasks_.empty()) return;
            task = std::move(tasks_.front());
            tasks_.pop();
        }
        task();   // run outside the lock
    }
}

#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

namespace py = pybind11;

py::array_t<double> callPayoffs(py::array_t<double> spots, double strike) {
    py::buffer_info buf = spots.request();
    if (buf.ndim != 1) throw std::runtime_error("expected a 1-D array");

    auto result = py::array_t<double>(buf.shape);
    py::buffer_info resBuf = result.request();

    const double* in  = static_cast<const double*>(buf.ptr);
    double*       out = static_cast<double*>(resBuf.ptr);

    for (ssize_t i = 0; i < buf.shape[0]; ++i) {
        double payoff = in[i] - strike;
        out[i] = payoff > 0.0 ? payoff : 0.0;
    }
    return result;
}

PYBIND11_MODULE(quantlib_cpp, m) {
    m.def("call_payoffs", &callPayoffs, py::arg("spots"), py::arg("strike"));
}
